mapper.update:
update outbox
set state = 'pending', updated_at = now()
where state = 'sending' and updated_at < #{deadline}

update outbox
set state = 'pending', retry_count = retry_count + 1, updated_at = now()
where state = 'sent' and sent_at < #{deadline} and retry_count < #{maxRetry}

update outbox
set state = 'dead', updated_at = now()
where state = 'sent' and sent_at < #{deadline} and retry_count >= #{maxRetry}
